# Generated from static/index.html so the app works even if the static folder is missing.
HTML = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Valor Inventory Agent</title>\n<style>\n:root{--bg:#f6f7f9;--card:#fff;--ink:#14171c;--mute:#6b7280;--line:#e5e7eb;--acc:#d62f2f;--ok:#15803d;--warn:#b45309;--blue:#1d4ed8}\n@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#181b21;--ink:#eceef2;--mute:#9aa1ad;--line:#2a2f38;--acc:#ef5350;--ok:#4ade80;--warn:#fbbf24;--blue:#60a5fa}}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,sans-serif}\nheader{display:flex;align-items:center;gap:12px;padding:14px 20px;background:var(--card);border-bottom:1px solid var(--line);flex-wrap:wrap}\nh1{font-size:17px;margin:0;flex:1}\nmain{max-width:1150px;margin:0 auto;padding:16px 20px 60px}\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:16px}\n.tile{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px}\n.tile b{display:block;font-size:20px}.tile span{color:var(--mute);font-size:12px}\nnav{display:flex;gap:4px;margin-bottom:12px;flex-wrap:wrap}\nnav button{background:none;border:0;padding:8px 12px;border-radius:8px;cursor:pointer;color:var(--mute);font:inherit}\nnav button.on{background:var(--card);color:var(--ink);border:1px solid var(--line)}\n.badge{background:var(--acc);color:#fff;border-radius:9px;padding:0 6px;font-size:11px;margin-left:4px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:auto}\ntable{width:100%;border-collapse:collapse}th,td{padding:8px 10px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}\nth{font-size:12px;color:var(--mute);font-weight:600}td.wrap{white-space:normal;min-width:200px}\nbutton.b,input,select{font:inherit;padding:6px 10px;border-radius:7px;border:1px solid var(--line);background:var(--card);color:var(--ink)}\nbutton.b{cursor:pointer}button.p{background:var(--acc);border-color:var(--acc);color:#fff}\n.bar{display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap;align-items:center}\n.pill{padding:1px 8px;border-radius:9px;font-size:12px;border:1px solid var(--line)}\n.confirmed{color:var(--blue)}.shipped{color:var(--warn)}.delivered{color:var(--ok)}.cancelled{color:var(--mute);text-decoration:line-through}\ndialog.wide{max-width:780px}dialog{max-height:92vh;overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card);color:var(--ink);max-width:460px;width:92%}\ndialog label{display:block;margin:8px 0 2px;font-size:12px;color:var(--mute)}dialog input,dialog select{width:100%}\n.log{font:12px ui-monospace,monospace;color:var(--mute);white-space:pre-wrap;margin-top:8px;max-height:140px;overflow:auto}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}fieldset{border:1px solid var(--line);border-radius:8px;margin:10px 0;padding:6px 10px 10px}legend{font-size:12px;color:var(--mute)}div.mrow{display:flex;flex-direction:column;padding:4px 6px;border-radius:6px}div.mrow input[data-v],div.mrow select[data-v]{opacity:.45}div.mrow.on{background:rgba(214,47,47,.08)}div.mrow.on input[data-v],div.mrow.on select[data-v]{opacity:1}label.cbl{display:inline-flex;align-items:center;gap:6px;margin:6px 14px 6px 0;color:var(--ink);font-size:13px}dialog label.cbl input{width:auto}@media(max-width:600px){.grid2{grid-template-columns:1fr}}\n.muted{color:var(--mute)}.neg{color:var(--acc)}.pos{color:var(--ok)}\n</style></head><body>\n<header><h1>Valor Inventory Agent</h1><span id=\"syncmsg\" class=\"muted\"></span>\n<button class=\"b p\" id=\"syncbtn\">Sync iCloud email</button><button class=\"b\" onclick=\"api('open_exports',{})\">Exports folder</button><button class=\"b\" id=\"setbtn\">Settings</button></header>\n<main>\n<div class=\"tiles\" id=\"tiles\"></div>\n<nav id=\"nav\"></nav>\n<div id=\"view\"></div>\n<div class=\"log\" id=\"log\"></div>\n</main>\n<dialog id=\"dlg\"><form method=\"dialog\" id=\"form\"></form></dialog>\n<script>\nconst $=s=>document.querySelector(s);\nconst money=n=>(n<0?'-':'')+'$'+Math.abs(+n||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});\nconst esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst api=(p,b)=>fetch('/api/'+p,b===undefined?{}:{method:'POST',body:JSON.stringify(b)}).then(r=>r.json());\nlet tab='inventory',data={},filter='';\nconst TABS=['inventory','orders','sales','limits','accounts','profiles','review'];\nconst SITES=['Pokemon Center','Target','Walmart','Best Buy','GameStop','Costco',\"Sam's Club\"];\nlet openSites={};\n\nasync function load(){\n  const [s,inv,ord,sal,rev,acc,prof,lim]=await Promise.all(['summary','inventory','orders','sales','review','vaccounts','vprofiles','limits'].map(p=>api(p)));\n  data={inv,ord,sal,rev,acc,prof,lim};\n  $('#tiles').innerHTML=[['On hand',s.units_on_hand+' units'],['Inventory cost',money(s.inventory_cost)],['Market value',money(s.inventory_market)],\n   ['Incoming',s.incoming_units+' units'],['Open orders',s.open_orders],['Profit (30d)',money(s.profit_30d)],['Profit (all)',money(s.profit)]]\n   .map(([l,v])=>`<div class=\"tile\"><b>${v}</b><span>${l}</span></div>`).join('');\n  $('#nav').innerHTML=TABS.map(t=>`<button class=\"${t==tab?'on':''}\" onclick=\"tab='${t}';render()\">${t[0].toUpperCase()+t.slice(1)}${t=='review'&&rev.length?`<span class=\"badge\">${rev.length}</span>`:''}</button>`).join('');\n  render();\n}\nfunction render(){\n  document.querySelectorAll('#nav button').forEach((b,i)=>b.classList.toggle('on',TABS[i]==tab));\n  $('#view').innerHTML=({inventory:vInv,orders:vOrd,sales:vSal,accounts:vAcc,profiles:vProf,limits:vLim,review:vRev})[tab]();\n}\nconst f=()=>`<input placeholder=\"Filter\u2026\" value=\"${esc(filter)}\" oninput=\"filter=this.value;render();this.focus()\" autofocus>`;\nfunction vInv(){\n  const rows=data.inv.filter(r=>(r.name+r.sku).toLowerCase().includes(filter.toLowerCase()));\n  return `<div class=\"bar\">${f()}<button class=\"b p\" onclick=\"invDlg()\">+ Add item</button></div><div class=\"card\"><table>\n  <tr><th>Item</th><th>SKU</th><th>Qty</th><th>Avg cost</th><th>Market</th><th>Value</th><th>Location</th><th></th></tr>\n  ${rows.map(r=>`<tr><td class=\"wrap\">${esc(r.name)}</td><td>${esc(r.sku)}</td><td>${r.qty}</td><td>${money(r.avg_cost)}</td>\n  <td>${r.market_price?money(r.market_price):'<span class=\"muted\">-</span>'}</td><td>${money(r.qty*(r.market_price||r.avg_cost))}</td><td>${esc(r.location)}</td>\n  <td><button class=\"b\" onclick=\"invDlg(${r.id})\">Edit</button> <button class=\"b\" onclick=\"saleDlg(${r.id})\" ${r.qty?'':'disabled'}>Sell</button></td></tr>`).join('')||'<tr><td class=\"muted\">No items yet.</td></tr>'}</table></div>`;\n}\nfunction vOrd(){\n  const rows=data.ord.filter(r=>(r.retailer+r.order_number+r.items.map(i=>i.name).join()).toLowerCase().includes(filter.toLowerCase()));\n  return `<div class=\"bar\">${f()}<button class=\"b p\" onclick=\"ordDlg()\">+ Manual order</button></div><div class=\"card\"><table>\n  <tr><th>Date</th><th>Retailer</th><th>Order #</th><th>Status</th><th>Items</th><th>Total</th><th>Tracking</th><th></th></tr>\n  ${rows.map(o=>`<tr><td>${esc(o.order_date||'')}</td><td>${esc(o.retailer)}</td><td>${esc(o.order_number)}</td>\n  <td><span class=\"pill ${o.status}\">${o.status}</span>${o.received?' <span class=\"pill pos\">in stock</span>':''}</td>\n  <td class=\"wrap\">${o.items.map(i=>`${i.qty}\u00d7 ${esc(i.name)}`).join('<br>')||'<span class=\"neg\">no items</span>'}</td>\n  <td>${o.total?money(o.total):''}</td><td>${esc(o.tracking)}</td>\n  <td><select onchange=\"setStatus(${o.id},this.value)\">${['confirmed','shipped','delivered','cancelled'].map(s=>`<option ${s==o.status?'selected':''}>${s}</option>`).join('')}</select>\n  <button class=\"b\" onclick=\"itemsDlg(${o.id})\">Items</button>\n  ${!o.received&&o.status!='cancelled'&&o.items.length?`<button class=\"b\" onclick=\"recv(${o.id})\">Receive</button>`:''}</td></tr>`).join('')||'<tr><td class=\"muted\">No orders yet. Click Sync.</td></tr>'}</table></div>`;\n}\nfunction vSal(){\n  return `<div class=\"card\"><table><tr><th>Date</th><th>Item</th><th>Qty</th><th>Price</th><th>Fees</th><th>Ship</th><th>Cost</th><th>Profit</th><th>Platform</th></tr>\n  ${data.sal.map(s=>{const p=s.sale_price*s.qty-s.fees-s.shipping-s.cost_basis*s.qty;return `<tr><td>${(s.sold_at||'').slice(0,10)}</td><td class=\"wrap\">${esc(s.item_name)}</td><td>${s.qty}</td><td>${money(s.sale_price)}</td><td>${money(s.fees)}</td><td>${money(s.shipping)}</td><td>${money(s.cost_basis)}</td><td class=\"${p<0?'neg':'pos'}\">${money(p)}</td><td>${esc(s.platform)}</td></tr>`}).join('')||'<tr><td class=\"muted\">No sales yet. Use Sell on an inventory item.</td></tr>'}</table></div>`;\n}\nfunction vRev(){\n  return `<div class=\"card\"><table><tr><th>Retailer</th><th>Subject</th><th>Why</th><th></th></tr>\n  ${data.rev.map(r=>`<tr><td>${esc(r.retailer)}</td><td class=\"wrap\">${esc(r.subject)}<div class=\"muted\">${esc((r.snippet||'').slice(0,160))}</div></td><td class=\"wrap\">${esc(r.reason)}</td>\n  <td><button class=\"b\" onclick=\"resolve(${r.id})\">Dismiss</button></td></tr>`).join('')||'<tr><td class=\"muted\">Nothing needs review.</td></tr>'}</table></div>`;\n}\n\nfunction groupBySite(list){const g={};list.forEach(r=>(g[r.site]=g[r.site]||[]).push(r));return Object.keys(g).sort().map(k=>[k,g[k]])}\nconst q=s=>JSON.stringify(s).replace(/\"/g,'&quot;');\nfunction siteBlock(site,count,inner,extra=''){const o=openSites[site]===true;return `<div class=\"card\" style=\"margin-bottom:10px\"><div style=\"padding:10px 12px;cursor:pointer;font-weight:600;display:flex;gap:10px;align-items:center\" onclick=\"openSites[${q(site)}]=${!o};render()\"><span>${o?'\u25be':'\u25b8'} ${esc(site)} <span class=\"muted\">(${count})</span></span>${extra}</div>${o?inner:''}</div>`}\nconst allSites=()=>[...new Set([...SITES,...data.acc.map(a=>a.site),...data.prof.map(p=>p.site)])];\nconst siteList=()=>`<datalist id=\"sites\">${allSites().map(s=>`<option value=\"${esc(s)}\">`).join('')}</datalist>`;\nlet sel={acc:new Set(),prof:new Set()};\nconst chk=(kind,id)=>`<input type=\"checkbox\" ${sel[kind].has(id)?'checked':''} onclick=\"event.stopPropagation();togSel('${kind}',${q(id)},this.checked)\">`;\nfunction togSel(kind,id,on){on?sel[kind].add(id):sel[kind].delete(id);updBulk()}\nfunction selAll(kind,ids,on){ids.forEach(i=>on?sel[kind].add(i):sel[kind].delete(i));render()}\nfunction updBulk(){const n=document.getElementById('bulkn');if(n)n.textContent=sel[tab=='accounts'?'acc':'prof'].size}\nconst flag=b=>b?'<span class=\"pill pos\">yes</span>':'<span class=\"muted\">no</span>';\nfunction bulkBar(kind){\n  const acc=kind=='acc';\n  return `<span class=\"muted\"><b id=\"bulkn\">${sel[kind].size}</b> ticked</span>\n  <button class=\"b\" onclick=\"bulkFlag('${kind}','selected',true)\">Mark Valor-selected</button>\n  <button class=\"b\" onclick=\"bulkFlag('${kind}','selected',false)\">Unmark</button>\n  <button class=\"b\" onclick=\"bulkDel('${kind}')\">Delete ticked</button>\n  <button class=\"b\" onclick=\"sel.${kind}.clear();render()\">Clear ticks</button>`;\n}\nasync function bulkFlag(kind,field,val){\n  const ids=[...sel[kind]];if(!ids.length)return alert('Tick some rows first.');\n  if(kind=='prof')await api('vprofiles/patch',{ids,changes:{[field]:val}});\n  else for(const [site,list] of groupBySite(data.acc.filter(a=>sel.acc.has(a.id+'||'+a.site)))){await api('vaccounts/patch',{site,ids:list.map(a=>a.id),changes:{[field]:val}})}\n  load();\n}\nasync function bulkDel(kind){\n  const ids=[...sel[kind]];if(!ids.length)return alert('Tick some rows first.');\n  if(!confirm(`Delete ${ids.length} ${kind=='acc'?'account(s)':'profile(s)'}? (Rejigged copies of deleted profiles go too.)`))return;\n  if(kind=='prof')await api('vprofiles/delete',{ids});\n  else for(const [site,list] of groupBySite(data.acc.filter(a=>sel.acc.has(a.id+'||'+a.site)))){await api('vaccounts/delete',{site,ids:list.map(a=>a.id)})}\n  sel[kind].clear();load();\n}\nfunction setByPath(o,path,v){const p=path.split('.');let t=o;p.slice(0,-1).forEach(k=>t=t[k]=t[k]||{});t[p[p.length-1]]=v}\nconst getP=(o,path)=>path.split('.').reduce((a,k)=>a==null?'':a[k],o);\nconst fld=(path,label,rec,type='text',x='')=>`<div><label>${label}</label><input data-p=\"${path}\" type=\"${type}\" value=\"${esc(getP(rec,path)??'')}\" ${x}></div>`;\nconst cb=(path,label,rec)=>`<label class=\"cbl\"><input type=\"checkbox\" data-p=\"${path}\" data-bool=\"1\" ${getP(rec,path)?'checked':''}> ${label}</label>`;\nfunction readForm(base){const rec=JSON.parse(JSON.stringify(base));document.querySelectorAll('#form [data-p]').forEach(e=>{const v=e.dataset.bool?e.checked:(e.type=='number'?(e.value===''?0:+e.value):e.value.trim());setByPath(rec,e.dataset.p,v)});return rec}\n\n/* ------------------------------ accounts */\nfunction vAcc(){\n  const rows=data.acc.filter(r=>(r.site+r.rec.email+r.rec.proxy).toLowerCase().includes(filter.toLowerCase()));\n  return `<div class=\"bar\">${f()}<button class=\"b p\" onclick=\"accDlg()\">+ Add account</button><button class=\"b\" onclick=\"accImport()\">Import Valor file</button><button class=\"b\" onclick=\"accExport()\">Export Valor file</button></div>\n  <div class=\"bar\">${bulkBar('acc')}</div>\n  ${groupBySite(rows).map(([s,l])=>siteBlock(s,l.length,`<table><tr><th><input type=\"checkbox\" onclick=\"selAll('acc',${q(l.map(a=>a.id+'||'+a.site))},this.checked)\"></th><th>Email</th><th>Password</th><th>Proxy</th><th>Session</th><th>Valor-selected</th><th></th></tr>${l.map(a=>`<tr><td>${chk('acc',a.id+'||'+a.site)}</td><td>${esc(a.rec.email)}</td><td><span class=\"muted\" style=\"cursor:pointer\" onclick=\"this.textContent=this.dataset.p\" data-p=\"${esc(a.rec.password)}\">${a.rec.password?'\u2022\u2022\u2022\u2022\u2022\u2022 (click)':''}</span></td><td>${esc(a.rec.proxy)}</td><td>${flag(a.rec.session)}</td><td>${flag(a.rec.selected)}</td><td><button class=\"b\" onclick=\"accDlg(${q(a.site)},${q(a.id)})\">Edit</button></td></tr>`).join('')}</table>`)).join('')||'<div class=\"card\"><table><tr><td class=\"muted\">No accounts yet. Use Import Valor file.</td></tr></table></div>'}${siteList()}`;\n}\nfunction accDlg(site,id){\n  const a=id?data.acc.find(x=>x.id==id&&x.site==site):null;const rec=a?a.rec:{id:'',email:'',password:'',proxy:'',session:false,selected:false};\n  dlg(`<div><label>Website</label><input id=\"accsite\" list=\"sites\" value=\"${esc(a?a.site:'')}\" required></div><div class=\"grid2\">`+fld('email','Account email',rec,'text','required')+fld('password','Password',rec)+fld('proxy','Proxy (host:port:user:pass)',rec)+fld('id','ID (normally = email)',rec)+`</div>`+cb('session','Keep session',rec)+cb('selected','Selected in Valor',rec)+(a?`<p><button type=\"button\" class=\"b\" onclick=\"delAcc(${q(a.site)},${q(a.id)})\">Delete account</button></p>`:''),\n  async()=>{const r=readForm(rec);return api('vaccounts/save',{site:$('#accsite').value,rec:r,old_id:a?a.id:null,old_email:a?a.rec.email:null})});\n}\nasync function delAcc(site,id){if(confirm('Delete this account?')){await api('vaccounts/delete',{site,ids:[id]});$('#dlg').close();load()}}\nfunction accImport(){\n  dlg(`<p class=\"muted\">Choose an accounts file exported from Valor. Existing accounts with the same ID are updated; nothing else is touched.</p><label>Valor accounts file (.json)</label><input type=\"file\" accept=\".json\" id=\"impfile\" required>`+inp('site','Website (leave blank to use the name inside the file)','')+`<label class=\"cbl\"><input type=\"checkbox\" id=\"impreplace\"> Replace all existing accounts for that website</label>`,\n  async fd=>{const f=$('#impfile').files[0];if(!f)return{error:'Choose a file'};const r=await api('vaccounts/import',{text:await f.text(),site:fd.site,replace:$('#impreplace').checked});if(!r.error)alert(`${r.site}: ${r.added} added, ${r.updated} updated`);return r});\n}\nfunction accExport(){\n  const sites=[...new Set(data.acc.map(a=>a.site))].sort();if(!sites.length)return alert('No accounts to export yet.');\n  dlg(`<label>Website</label><select id=\"exsite\">${sites.map(s=>`<option>${esc(s)}</option>`).join('')}</select><label class=\"cbl\"><input type=\"checkbox\" id=\"exsel\"> Only accounts marked Valor-selected</label><p class=\"muted\">Creates a file in the same format Valor exports. Import it in Valor's Accounts page.</p>`,\n  async()=>{const fn=`valor_accounts_${$('#exsite').value.replace(/\\W+/g,'_')}.json`;const r=await api('vaccounts/export',{site:$('#exsite').value,selected_only:$('#exsel').checked,filename:fn});if(r.error)return r;if(!window.pywebview)saveText(fn,r.json);alert(r.count+' accounts exported to:\\n'+r.saved_to);return r});\n}\nfunction saveText(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;document.body.appendChild(a);a.click();a.remove()}\n\n/* ------------------------------ profiles */\nconst mask=n=>n?'\u2022\u2022\u2022\u2022 '+String(n).replace(/\\D/g,'').slice(-4):'';\nfunction vProf(){\n  const rows=data.prof.filter(r=>(r.site+r.rec.name+r.rec.email+r.rec.shipping.addressLine1+r.rec.shipping.firstName+r.rec.shipping.lastName).toLowerCase().includes(filter.toLowerCase()));\n  return `<div class=\"bar\">${f()}<button class=\"b p\" onclick=\"profDlg()\">+ Add profile</button><button class=\"b\" onclick=\"profImport()\">Import Valor file</button><button class=\"b\" onclick=\"profExport()\">Export Valor file</button><button class=\"b\" onclick=\"massEditDlg()\">Mass edit\u2026</button><button class=\"b\" onclick=\"massEditDlg('Billing')\">Mass edit billing\u2026</button><button class=\"b\" onclick=\"bulkAddrDlg()\">Change addresses\u2026</button></div>\n  <div class=\"bar\">${bulkBar('prof')}</div>\n  ${groupBySite(rows).map(([s,l])=>siteBlock(s,l.length,`<div style=\"overflow:auto\"><table><tr><th><input type=\"checkbox\" onclick=\"selAll('prof',${q(l.map(p=>p.id))},this.checked)\"></th><th>Profile</th><th>Ship to</th><th>Address</th><th>City / State / ZIP</th><th>Email</th><th>Phone</th><th>Card</th><th>Valor-sel.</th><th></th></tr>${l.map(p=>{const r=p.rec,sh=r.shipping;return `<tr><td>${chk('prof',p.id)}</td><td>${p.group_id?'<span class=\"muted\">\u21b3 </span>':''}${esc(r.name)}</td><td>${esc(sh.firstName+' '+sh.lastName)}</td><td>${esc(sh.addressLine1)}${sh.addressLine2?', '+esc(sh.addressLine2):''}</td><td>${esc(sh.city)}, ${esc(sh.state)} ${esc(sh.zipCode)}</td><td>${esc(r.email)}</td><td>${esc(r.phoneNumber)}</td><td>${esc(r.card.type)} ${mask(r.card.number)}</td><td>${flag(r.selected)}</td><td><button class=\"b\" onclick=\"profDlg(${q(p.id)})\">Edit</button>${p.group_id?'':` <button class=\"b\" onclick=\"jigDlg(${q(p.id)})\">Rejig</button>`}</td></tr>`}).join('')}</table></div>`)).join('')||'<div class=\"card\"><table><tr><td class=\"muted\">No profiles yet. Use Import Valor file.</td></tr></table></div>'}${siteList()}`;\n}\nconst BLANK={name:'',email:'',phoneNumber:'',billingSameAsShipping:true,oneCheckout:false,quickTask:false,card:{holder:'',number:'',expiration:'',cvv:'',type:''},\n  shipping:{firstName:'',lastName:'',addressLine1:'',addressLine2:'',city:'',countryName:'United States',countryCode:'US',state:'',zipCode:''},\n  billing:{firstName:'',lastName:'',addressLine1:'',addressLine2:'',city:'',countryName:'United States',countryCode:'US',state:'',zipCode:''},id:'',totalSpent:0,selected:false};\nconst addrFields=(k,rec)=>fld(k+'.firstName','First name',rec)+fld(k+'.lastName','Last name',rec)+fld(k+'.addressLine1','Address line 1',rec)+fld(k+'.addressLine2','Address line 2',rec)+fld(k+'.city','City',rec)+fld(k+'.state','State',rec)+fld(k+'.zipCode','ZIP / postal code',rec)+fld(k+'.countryCode','Country code (US)',rec)+fld(k+'.countryName','Country name',rec);\nfunction profDlg(id){\n  const p=id?data.prof.find(x=>x.id==id):null;\n  const rec=p?p.rec:JSON.parse(JSON.stringify(BLANK));\n  const hasExtra=['personalCustomsCode','pinCode','idNumber','birthday'].some(k=>k in rec);\n  dlg(`<div class=\"grid2\"><div><label>Website</label><input id=\"profsite\" list=\"sites\" value=\"${esc(p?p.site:'')}\" required></div>`+fld('name','Profile name',rec,'text','required')+fld('email','Email',rec)+fld('phoneNumber','Phone number',rec)+`</div>\n  <div style=\"margin:8px 0\">${cb('billingSameAsShipping','Billing same as shipping',rec)}${cb('oneCheckout','One checkout',rec)}${cb('quickTask','Quick task',rec)}${cb('selected','Selected in Valor',rec)}</div>\n  <fieldset><legend>Card</legend><div class=\"grid2\">${fld('card.holder','Name on card',rec)}${fld('card.number','Card number',rec,'text','autocomplete=off')}${fld('card.expiration','Expiration (MM/YY)',rec)}${fld('card.cvv','CVV',rec,'text','autocomplete=off')}\n  <div><label>Card type</label><select data-p=\"card.type\">${['','visa','mastercard','amex','discover'].map(t=>`<option value=\"${t}\" ${rec.card.type==t?'selected':''}>${t||'(auto-detect)'}</option>`).join('')}</select></div>${fld('totalSpent','Total spent',rec,'number','step=0.01')}</div></fieldset>\n  <fieldset><legend>Shipping</legend><div class=\"grid2\">${addrFields('shipping',rec)}</div></fieldset>\n  <fieldset><legend>Billing</legend><div class=\"grid2\">${addrFields('billing',rec)}</div></fieldset>\n  <fieldset><legend>Other (optional)</legend><div class=\"grid2\">${['personalCustomsCode','pinCode','idNumber','birthday'].map(k=>fld(k,{personalCustomsCode:'Personal customs code',pinCode:'PIN code',idNumber:'ID number',birthday:'Birthday'}[k],rec)).join('')}</div></fieldset>`\n  +(p?`<p><button type=\"button\" class=\"b\" onclick=\"delProf(${q(p.id)})\">Delete profile</button></p>`:''),\n  async()=>{const r=readForm(rec);\n    if(r.billingSameAsShipping&&(!p||!p.rec.billingSameAsShipping)){r.billing={...r.billing,...r.shipping}}\n    if(!r.card.type&&r.card.number){const n=r.card.number.replace(/\\D/g,'');r.card.type=/^4/.test(n)?'visa':/^(5[1-5]|2[2-7])/.test(n)?'mastercard':/^3[47]/.test(n)?'amex':/^(6011|65)/.test(n)?'discover':''}\n    return api('vprofiles/save',{site:$('#profsite').value,rec:r,id:p?p.id:null,group_id:p?p.group_id:null})},'wide');\n}\nasync function delProf(id){if(confirm('Delete this profile (and its rejigged copies)?')){await api('vprofiles/delete',{ids:[id]});$('#dlg').close();load()}}\nfunction profImport(){\n  dlg(`<p class=\"muted\">Choose a profiles file exported from Valor. Profiles with the same ID are updated; every field in the file is kept exactly as-is.</p><label>Valor profiles file (.json)</label><input type=\"file\" accept=\".json\" id=\"impfile\" required><label>Website these profiles are for</label><input name=\"site\" list=\"sites\" required placeholder=\"e.g. Pokemon Center US\"><label class=\"cbl\"><input type=\"checkbox\" id=\"impreplace\"> Replace all existing profiles for that website</label>`+siteList(),\n  async fd=>{const f=$('#impfile').files[0];if(!f)return{error:'Choose a file'};const r=await api('vprofiles/import',{text:await f.text(),site:fd.site,replace:$('#impreplace').checked});if(!r.error)alert(`${r.added} added, ${r.updated} updated`);return r});\n}\nfunction profExport(){\n  const sites=[...new Set(data.prof.map(p=>p.site))].sort();if(!sites.length)return alert('No profiles to export yet.');\n  dlg(`<label>Website</label><select id=\"exsite\"><option value=\"\">All websites</option>${sites.map(s=>`<option>${esc(s)}</option>`).join('')}</select>\n  <label class=\"cbl\"><input type=\"checkbox\" id=\"exsel\"> Only profiles marked Valor-selected</label><label class=\"cbl\"><input type=\"checkbox\" id=\"exo\" checked> Include original profiles</label><label class=\"cbl\"><input type=\"checkbox\" id=\"exj\" checked> Include rejigged copies</label><p class=\"muted\">Creates a file in the same format Valor exports. Import it in Valor's Profiles page.</p>`,\n  async()=>{const fn='valor_profiles'+($('#exsite').value?'_'+$('#exsite').value.replace(/\\W+/g,'_'):'')+'.json';const r=await api('vprofiles/export',{site:$('#exsite').value,selected_only:$('#exsel').checked,include_originals:$('#exo').checked,include_jigs:$('#exj').checked,filename:fn});if(r.error)return r;if(!window.pywebview)saveText(fn,r.json);alert(r.count+' profiles exported to:\\n'+r.saved_to);return r});\n}\nfunction jigDlg(id){\n  const p=data.prof.find(x=>x.id==id);const sh=p.rec.shipping;const existing=data.prof.filter(x=>x.group_id==id).length;\n  const run=async save=>{const fd=Object.fromEntries(new FormData($('#form')));const r=await api('vprofiles/jig',{id,count:+fd.count,use_units:!!fd.use_units,seed:fd.seed,save,replace:true});if(r.error){alert(r.error);return false}\n    $('#jigout').innerHTML=`<b>${r.variants.length} of ${fd.count} available</b><br>`+r.variants.map(v=>esc(v.addressLine1)+(v.addressLine2?', '+esc(v.addressLine2):'')).join('<br>');return true};\n  dlg(`<b>${esc(p.rec.name)}</b><div class=\"muted\">${esc(sh.addressLine1)} ${esc(sh.addressLine2)}, ${esc(sh.city)} ${esc(sh.state)} ${esc(sh.zipCode)}</div><p class=\"muted\">Makes copies of this profile with alternate spellings of the same address (St/Street, N/North, Apt/Unit/#). City, state and ZIP never change. ${existing?`<b>Saving replaces its ${existing} existing copies.</b>`:''}</p>`+inp('count','How many copies',10,'number','min=1 max=200')+`<label class=\"cbl\"><input type=\"checkbox\" name=\"use_units\" checked> Add unit lines (Apt 3, #B\u2026) when there is no line 2</label>`+inp('seed','Seed (optional; same seed = same result)','')+`<p><button type=\"button\" class=\"b\" id=\"prevbtn\">Preview</button></p><div id=\"jigout\" class=\"log\" style=\"max-height:180px\"></div>`,\n  async()=>{const ok=await run(true);return ok?null:{error:'No copies were saved'}});\n  $('#prevbtn').onclick=()=>run(false);\n}\n\nfunction fieldDefs(){return [\n ['Contact',[['email','Email'],['phoneNumber','Phone number']]],\n ['Switches',[['billingSameAsShipping','Billing same as shipping','bool'],['oneCheckout','One checkout','bool'],['quickTask','Quick task','bool'],['selected','Selected in Valor','bool']]],\n ['Card',[['card.holder','Name on card'],['card.number','Card number'],['card.expiration','Expiration (MM/YY)'],['card.cvv','CVV'],['card.type','Card type','type']]],\n ['Shipping',addrKeys('shipping')],\n ['Billing',addrKeys('billing')],\n ['Other',[['personalCustomsCode','Personal customs code'],['pinCode','PIN code'],['idNumber','ID number'],['birthday','Birthday'],['totalSpent','Total spent','num']]]]}\nfunction addrKeys(k){return [['firstName','First name'],['lastName','Last name'],['addressLine1','Address line 1'],['addressLine2','Address line 2'],['city','City'],['state','State'],['zipCode','ZIP'],['countryCode','Country code'],['countryName','Country name']].map(([a,b])=>[k+'.'+a,b])}\nfunction massRow([p,l,t]){\n  const inpt=t=='bool'?`<select data-v=\"${p}\"><option value=\"true\">On</option><option value=\"false\">Off</option></select>`:t=='type'?`<select data-v=\"${p}\">${['visa','mastercard','amex','discover'].map(x=>`<option>${x}</option>`).join('')}</select>`:`<input data-v=\"${p}\" type=\"${t=='num'?'number':'text'}\" ${t=='num'?'step=0.01':''}>`;\n  return `<div class=\"mrow\"><label class=\"cbl\"><input type=\"checkbox\" data-c=\"${p}\" onchange=\"this.closest('.mrow').classList.toggle('on',this.checked)\"> ${l}</label>${inpt}</div>`}\nfunction massEditDlg(only){\n  const sites=[...new Set(data.prof.map(p=>p.site))].sort();if(!sites.length)return alert('No profiles yet.');\n  const ticked=sel.prof.size;\n  const groups=fieldDefs().filter(g=>!only||g[0]==only);\n  dlg(`<p class=\"muted\">Tick each field you want to change, type the new value, and it is set on every profile in scope. Fields you don't tick are left alone. Export first if unsure; there is no undo.</p>\n  <div class=\"grid2\"><div><label>Website</label><select id=\"mesite\">${sites.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div>\n  <div><label>Apply to</label><select id=\"mescope\"><option value=\"all\">All profiles for that website</option><option value=\"ticked\" ${ticked?'selected':''}>Only the ${ticked} ticked rows</option><option value=\"orig\">Original profiles only (no rejigged copies)</option></select></div></div>\n  ${groups.map(([g,rows])=>`<fieldset><legend>${g}</legend><div class=\"grid2\">${rows.map(massRow).join('')}</div></fieldset>`).join('')}`,\n  async()=>{const changes={};document.querySelectorAll('#form [data-c]').forEach(c=>{if(!c.checked)return;const el=document.querySelector(`#form [data-v=\"${c.dataset.c}\"]`);let v=el.value;if(v==='true')v=true;else if(v==='false')v=false;else if(el.type=='number')v=v===''?0:+v;changes[c.dataset.c]=typeof v=='string'?v.trim():v});\n    if(!Object.keys(changes).length)return{error:'Tick at least one field to change'};\n    const site=$('#mesite').value,sc=$('#mescope').value;let ids=data.prof.filter(p=>p.site==site&&(sc=='all'||(sc=='orig'&&!p.group_id)||(sc=='ticked'&&sel.prof.has(p.id)))).map(p=>p.id);\n    if(!ids.length)return{error:'No profiles in that scope'};\n    if(changes['billing.addressLine1']!==undefined||Object.keys(changes).some(k=>k.startsWith('billing.')))if(!('billingSameAsShipping' in changes)&&confirm('You are changing billing fields. Also switch off \u201cBilling same as shipping\u201d on these profiles so the new billing is used?'))changes.billingSameAsShipping=false;\n    if(!confirm(`Change ${Object.keys(changes).length} field(s) on ${ids.length} profiles?`))return{error:'Cancelled'};\n    const r=await api('vprofiles/patch',{ids,changes});if(!r.error)alert(r.updated+' profiles updated');return r},'wide');\n}\n\nfunction vLim(){\n  return `<div class=\"bar\"><button class=\"b p\" onclick=\"limDlg()\">+ Add limit</button><span class=\"muted\">Track units bought per retailer against the store's posted limit. Counts come from your orders (cancelled ones excluded).</span></div><div class=\"card\"><table><tr><th>Retailer</th><th>Product contains</th><th>Limit</th><th>Window</th><th>Bought</th><th>Left</th><th></th></tr>\n  ${data.lim.map(l=>`<tr><td>${esc(l.retailer)}</td><td>${esc(l.product)}</td><td>${l.max_qty}</td><td>${l.window_days?l.window_days+' days':'all time'}</td><td class=\"${l.over?'neg':''}\">${l.bought}</td><td class=\"${l.over?'neg':'pos'}\">${l.over?'over limit':l.remaining}</td><td><button class=\"b\" onclick=\"limDlg(${l.id})\">Edit</button></td></tr>`).join('')||'<tr><td class=\"muted\">No limits yet. Add one, e.g. Target / Elite Trainer Box / 2.</td></tr>'}</table></div>`;\n}\nfunction limDlg(id){\n  const l=data.lim.find(x=>x.id==id)||{retailer:'',product:'',max_qty:1,window_days:0};\n  dlg(`<label>Retailer</label><input name=\"retailer\" list=\"sites\" value=\"${esc(l.retailer)}\" required>`+inp('product','Product name contains',l.product,'text','required')+inp('max_qty','Max units',l.max_qty,'number','min=1')+inp('window_days','Window in days (0 = all time)',l.window_days,'number','min=0')+siteList()+(id?`<p><button type=\"button\" class=\"b\" onclick=\"delLim(${id})\">Delete</button></p>`:''),\n  fd=>api('limits/save',{...fd,id}));\n}\nasync function delLim(id){if(confirm('Delete this limit?')){await api('limits/delete',{id});$('#dlg').close();load()}}\nfunction bulkAddrDlg(){\n  const sites=[...new Set(data.prof.map(p=>p.site))].sort();if(!sites.length)return alert('No profiles yet.');\n  const ticked=sel.prof.size;\n  const a={addressLine1:'',addressLine2:'',city:'',state:'',zipCode:'',countryCode:'US',countryName:'United States'};\n  dlg(`<p class=\"muted\">Moves profiles to a new address. Choose billing only to leave shipping untouched. No backup is made, so export first if unsure.</p><label>Website</label><select id=\"basite\">${sites.map(s=>`<option>${esc(s)}</option>`).join('')}</select>\n  <label>Which address</label><select id=\"batarget\"><option value=\"both\">Shipping (billing follows if \u201csame as shipping\u201d)</option><option value=\"shipping\">Shipping only</option><option value=\"billing\">Billing only</option></select><label>Apply to</label><select id=\"bascope\"><option value=\"all\">All profiles for that website</option><option value=\"ticked\" ${ticked?'selected':''}>Only the ${ticked} ticked rows</option></select><div class=\"grid2\">${fld('addressLine1','Address line 1',a)}${fld('addressLine2','Address line 2',a)}${fld('city','City',a)}${fld('state','State',a)}${fld('zipCode','ZIP',a)}${fld('countryCode','Country code',a)}</div>\n  <label>Real unit numbers (optional, one per line or comma-separated, e.g. Unit 1, Unit 2, Unit 3)</label><textarea id=\"baunits_list\" rows=\"3\" style=\"width:100%\" placeholder=\"Leave blank to skip. Units are handed out to profiles in rotation as address line 2.\"></textarea><label class=\"cbl\"><input type=\"checkbox\" id=\"baunique\"> Give each profile its own spelling of this address (rejig)</label><label class=\"cbl\"><input type=\"checkbox\" id=\"baunits\" checked> Allow unit lines (Apt 3, #B\u2026)</label>`,\n  async()=>{const addr=readForm(a);const ids=$('#bascope').value=='ticked'?[...sel.prof]:null;if($('#bascope').value=='ticked'&&!ids.length)return{error:'Tick some profiles first'};\n    if(!confirm('Update '+(ids?ids.length:'all')+' profiles for '+$('#basite').value+'?'))return{error:'Cancelled'};\n    const r=await api('vprofiles/bulk_address',{site:$('#basite').value,ids,address:addr,unique:$('#baunique').checked,use_units:$('#baunits').checked,target:$('#batarget').value,units:$('#baunits_list').value.split(/[\\n,]+/)});if(!r.error)alert(r.updated+' profiles updated. '+(r.note||''));return r},'wide');\n}\nfunction dlg(html,onok,wide){\n  $('#dlg').classList.toggle('wide',!!wide);\n  $('#form').innerHTML=html+`<div style=\"margin-top:14px;display:flex;gap:8px;justify-content:flex-end\"><button class=\"b\" type=\"button\" onclick=\"$('#dlg').close()\">Cancel</button><button class=\"b p\" type=\"submit\">Save</button></div>`;\n  $('#form').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData($('#form')));const btn=$('#form button[type=submit]');btn.disabled=true;\n    try{const r=await onok(fd);if(r&&r.error){alert(r.error);return}$('#dlg').close();load()}catch(err){alert('Something went wrong: '+err.message)}finally{btn.disabled=false}};\n  $('#dlg').showModal();\n}\nconst inp=(n,l,v='',t='text',x='')=>`<label>${l}</label><input name=\"${n}\" type=\"${t}\" value=\"${esc(v)}\" ${x}>`;\nfunction invDlg(id){\n  const r=data.inv.find(x=>x.id==id)||{};\n  dlg(inp('name','Name',r.name,'text','required')+inp('sku','SKU',r.sku)+inp('qty','Quantity',r.qty??0,'number')+inp('avg_cost','Avg cost each',r.avg_cost??0,'number','step=0.01')+inp('market_price','Market price each',r.market_price??0,'number','step=0.01')+inp('location','Location',r.location)+inp('notes','Notes',r.notes)\n   +(id?`<p><button type=\"button\" class=\"b\" onclick=\"delInv(${id})\">Delete item</button></p>`:''),\n   fd=>id?api('inventory/update',{...fd,id}):api('inventory',{name:fd.name,sku:fd.sku,qty:fd.qty,avg_cost:fd.avg_cost,market_price:fd.market_price}));\n}\nasync function delInv(id){if(confirm('Delete this item?')){await api('inventory/delete',{id});$('#dlg').close();load()}}\nfunction saleDlg(id){\n  const r=data.inv.find(x=>x.id==id);\n  dlg(`<b>${esc(r.name)}</b> <span class=\"muted\">(${r.qty} on hand)</span>`+inp('qty','Qty sold',1,'number',`min=1 max=${r.qty}`)+inp('sale_price','Sale price each',r.market_price||'','number','step=0.01 required')+inp('fees','Fees total',0,'number','step=0.01')+inp('shipping','Shipping cost',0,'number','step=0.01')+inp('platform','Platform (eBay, TCGplayer\u2026)'),\n   fd=>api('sale',{...fd,inventory_id:id}));\n}\nfunction ordDlg(){\n  dlg(inp('retailer','Retailer','Target')+inp('order_number','Order number','','text','required')+inp('date','Date',new Date().toISOString().slice(0,10),'date')+inp('total','Total','','number','step=0.01')+\n   inp('item','First item name')+inp('qty','Qty',1,'number')+inp('price','Unit price','','number','step=0.01'),\n   fd=>api('orders',{retailer:fd.retailer,order_number:fd.order_number,date:fd.date,total:fd.total?+fd.total:null,items:fd.item?[{name:fd.item,qty:+fd.qty,price:+fd.price||0}]:[]}));\n}\nfunction itemsDlg(id){\n  const o=data.ord.find(x=>x.id==id);\n  const lines=o.items.map(i=>`${i.qty} | ${i.unit_price} | ${i.name}`).join('\\n');\n  dlg(`<label>One item per line: qty | unit price | name</label><textarea name=\"t\" rows=\"7\" style=\"width:100%;font:inherit\">${esc(lines)}</textarea>`,\n   fd=>api('orders/items',{id,items:fd.t.split('\\n').map(l=>l.split('|').map(s=>s.trim())).filter(p=>p.length>=3&&p[2]).map(p=>({qty:+p[0]||1,price:+p[1]||0,name:p.slice(2).join('|')}))}));\n}\nasync function setStatus(id,status){await api('orders/status',{id,status});load()}\nasync function recv(id){await api('orders/receive',{id});load()}\nasync function resolve(id){await api('review/resolve',{id});load()}\n$('#setbtn').onclick=async()=>{\n  const s=await api('settings');\n  dlg(`<p class=\"muted\">Use an <b>app-specific password</b> from account.apple.com \u2192 Sign-In and Security. It stays on this computer in config.json.</p>`+inp('email','iCloud email',s.email,'email')+inp('password','App-specific password','','password',`placeholder=\"${s.has_password?'(saved - leave blank to keep)':'xxxx-xxxx-xxxx-xxxx'}\"`)+inp('folder','Mail folder',s.folder)+inp('days','Look back (days)',s.days,'number'),fd=>api('settings',fd));\n};\nlet timer;\n$('#syncbtn').onclick=async()=>{const r=await api('sync',{});if(r.error&&r.error!='already running')return alert(r.error);poll()};\nasync function poll(){\n  const s=await api('sync');\n  $('#syncbtn').disabled=s.running;$('#syncmsg').textContent=s.running?'Syncing\u2026':'';\n  $('#log').textContent=(s.log||[]).slice(-30).join('\\n')+(s.error?'\\nERROR: '+s.error:'')+(s.stats?'\\nDone: '+JSON.stringify(s.stats):'');\n  if(s.running)timer=setTimeout(poll,1000);else load();\n}\nload();poll();\n</script></body></html>\n"
